import { useState, useEffect } from "react";
import { fetchData } from "../utils/fetchData.js";

const useMedia = () => {
  const [mediaArray, setMediaArray] = useState([]);

  useEffect(() => {
    const getMedia = async () => {
      try {
        const json = await fetchData(import.meta.env.VITE_MEDIA_API + "/media");

        const authURL = import.meta.env.VITE_AUTH_API;

        const newArray = await Promise.all(
          json.map(async (item) => {
            const user = await fetchData(authURL + "/users/" + item.user_id);

            return {
              ...item,
              username: user.username,
            };
          }),
        );

        setMediaArray(newArray);
      } catch (error) {
        console.error("Failed to fetch media: ", error);
      }
    };

    getMedia();
  }, []);

  return { mediaArray };
};

const useAuthentication = () => {
  const postLogin = async (inputs) => {
    const fetchOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(inputs),
    };
    const loginResult = await fetchData(
      import.meta.env.VITE_AUTH_API + "/auth/login",
      fetchOptions,
    );
    return loginResult;
  };

  return { postLogin };
};

const useUser = () => {
  const getUserByToken = async (token) => {
    const fetchOptions = {
      method: "GET",
      headers: {
        Authorization: `Bearer ${token}`,
      },
    };

    return await fetchData(
      import.meta.env.VITE_AUTH_API + "/users/token",
      fetchOptions,
    );
  };

  const postUser = async (inputs) => {
    const fetchOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(inputs),
    };

    return await fetchData(
      import.meta.env.VITE_AUTH_API + "/users",
      fetchOptions,
    );
  };

  return { postUser, getUserByToken };
};

const useFile = () => {
  const postFile = async (file, token) => {
    const formData = new FormData();

    formData.append("file", file);

    const fetchOptions = {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
      },
      body: formData,
    };

    const response = await fetchData(
      import.meta.env.VITE_UPLOAD_SERVER + "/upload",
      fetchOptions,
    );

    return response;
  };

  const postMedia = async (fileData, inputs, token) => {
    // TODO: create a suitable object for Media API: without media_id, user_id, thumbnail and created_at. All those are generated by the API. See the media API documentation.
    const mediaData= {
      title: inputs.title,
      description: inputs.description,
      filename: fileData.filename,
      media_type:fileData.media_type,
      filesize:fileData.filesize,
    }
    const fetchOptions = {
      method: "POST",
      headers: {
        'Content-Type': 'application/json',
        Authorization: "Bearer " + token,
      },
      body: JSON.stringify(mediaData),
    };

    const mediaResponse = fetchData(import.meta.env.VITE_MEDIA_API + '/media', fetchOptions);
    // TODO: post the data to Media API and get the data as MediaResponse
    return await mediaResponse;
  };

  return { postFile, postMedia };
};

export { useMedia, useAuthentication, useUser, useFile };
